class Breaker:
    def __init__(self, threshold=0.5, window=20, cooldown=30):
        self.state, self.opened_at = 'closed', 0
        self.results = []  # True = lỗi
        self.threshold, self.window, self.cooldown = threshold, window, cooldown

    def call(self, fn, fallback):
        now = time.monotonic()
        if self.state == 'open':
            if now - self.opened_at < self.cooldown:
                return fallback()
            self.state = 'half-open'
        try:
            r = fn()
            self._record(False)
            if self.state == 'half-open': self.state = 'closed'
            return r
        except Exception:
            self._record(True)
            if self.state == 'half-open' or self._fail_rate() >= self.threshold:
                self.state, self.opened_at = 'open', now
            return fallback()

    def _record(self, failed):
        self.results = (self.results + [failed])[-self.window:]

    def _fail_rate(self):
        return sum(self.results) / len(self.results) if len(self.results) >= self.window else 0
